<script setup lang="ts">
import {ref,onMounted,onUnmounted,watch} from 'vue'
import {Trash2,Download,RefreshCw} from 'lucide-vue-next'
import Sheet from '../components/Sheet.vue'
import {useLocal} from '../stores/local'
import {exportLocalBackup} from '../repositories/local-backup'
import type {StoryDeletionPlan,StoryDeletionReceipt} from '../repositories/local-deletion'
const props=defineProps<{storyIds:string[]}>(),emit=defineEmits<{close:[];deleted:[StoryDeletionReceipt]}>(),store=useLocal(),plan=ref<StoryDeletionPlan|null>(null),receipt=ref<StoryDeletionReceipt|null>(null),loading=ref(true),busy=ref(false),error=ref(''),confirmed=ref(false),password=ref(''),backupSaved=ref(false)
const selected=[...props.storyIds],control=new AbortController();let disposed=false,operationId=crypto.randomUUID(),loadEpoch=0
const kinds={card:'角色卡',world:'互动世界',asset:'素材',session:'角色对话',companion:'伴侣',agentRun:'助手记录',settings:'关联记录',task:'任务',mediaJob:'媒体任务'} as Record<string,string>
function shortName(value:string){const characters=typeof Intl.Segmenter==='function'?Array.from(new Intl.Segmenter('zh',{granularity:'grapheme'}).segment(value),part=>part.segment):Array.from(value);return characters.length>72?characters.slice(0,72).join('')+'…':value}
async function load(){const vault=store.vault;if(!vault||busy.value)return;const ticket=++loadEpoch;loading.value=true;confirmed.value=false;error.value='';try{const next=await vault.previewStoryDeletion(selected,control.signal);if(!disposed&&store.vault===vault&&ticket===loadEpoch){plan.value=next;operationId=crypto.randomUUID()}}catch(e){if(!disposed&&store.vault===vault&&ticket===loadEpoch)error.value=(e as Error).message}finally{if(!disposed&&store.vault===vault&&ticket===loadEpoch)loading.value=false}}
async function backup(){const vault=store.vault;if(!vault||busy.value)return;busy.value=true;error.value='';try{const bytes=await exportLocalBackup(vault,password.value,false,control.signal);if(disposed||store.vault!==vault||!vault.unlocked)return;const url=URL.createObjectURL(new Blob([Uint8Array.from(bytes)],{type:'application/octet-stream'})),a=document.createElement('a');a.href=url;a.download='书籍删除前备份.storyvault';a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);backupSaved.value=true;password.value=''}catch(e){if(!disposed&&store.vault===vault)error.value=(e as Error).message}finally{if(!disposed&&store.vault===vault)busy.value=false}}
async function remove(){const vault=store.vault,current=plan.value;if(!vault||!current||busy.value||!confirmed.value||current.blockers.length||current.activeTasks.length)return;busy.value=true;error.value='';try{const result=await vault.deleteStories(operationId,current.storyIds,current.fingerprint,control.signal);if(!disposed&&store.vault===vault){receipt.value=result;emit('deleted',result)}}catch(e){if(!disposed&&store.vault===vault)error.value=(e as Error).message}finally{if(!disposed&&store.vault===vault)busy.value=false}}
function close(){control.abort();emit('close')}
watch(()=>store.vault,close)
onMounted(()=>{void load();window.addEventListener('reader-local-locked',close)})
onUnmounted(()=>{disposed=true;control.abort();password.value='';window.removeEventListener('reader-local-locked',close)})
</script>
<template><Sheet title="删除书籍" return-focus="[aria-label='导入书籍']" @close="close"><div class="book-delete"><p v-if="loading" role="status">正在检查关联…</p><p v-if="error" class="final-error" role="alert">{{error}}</p><div v-if="receipt" class="book-delete-result" role="status"><Trash2 :size="26"/><h3>{{receipt.storyIds.length}} 本书已删除</h3><p>{{receipt.documentIds.length}} 项记录及 {{receipt.historyVersions}} 个历史版本已清理。</p><RouterLink to="/local/settings/data" @click="emit('close')">从删除前备份恢复</RouterLink><button class="final-primary" @click="emit('close')">完成</button></div><template v-else-if="plan"><header><h3>{{plan.names.length===1?shortName(plan.names[0]!):plan.names.length+' 本书'}}</h3><p class="final-subtle">{{plan.counts.branch||0}} 条故事线 · {{plan.items.length}} 项记录 · {{plan.historyVersions}} 个历史版本</p></header><details class="book-delete-names"><summary>查看所选书籍</summary><ul aria-label="所选书籍"><li v-for="(name,index) in plan.names" :key="index">{{name}}</li></ul></details><ul aria-label="删除影响" class="book-delete-items"><li v-for="item in plan.items.slice(0,80)" :key="item.id"><span>{{item.label}}</span><small>{{item.versions}} 个版本</small></li><li v-if="plan.items.length>80">另有 {{plan.items.length-80}} 项</li></ul><section v-if="plan.blockers.length||plan.activeTasks.length" class="book-delete-blockers"><h4>先处理关联</h4><ul><li v-for="item in [...plan.blockers,...plan.activeTasks].slice(0,80)" :key="item.id">{{item.label}} · {{kinds[item.kind]||'关联内容'}}</li></ul></section><details><summary><Download :size="17"/>{{backupSaved?'备份文件已导出':'先导出加密备份'}}</summary><form @submit.prevent="backup"><label>备份口令<input v-model="password" type="password" autocomplete="new-password" minlength="8" maxlength="1024" :disabled="busy" required></label><button :disabled="busy||password.length<8">导出私人库备份</button></form></details><label v-if="!plan.blockers.length&&!plan.activeTasks.length" class="book-delete-confirm"><input v-model="confirmed" type="checkbox" :disabled="busy">删除这些书籍及关联正文、候选和笔记。</label><div class="book-delete-actions"><button :disabled="busy" @click="load"><RefreshCw :size="17"/>重新检查</button><button class="book-delete-danger" :disabled="busy||!confirmed||!!plan.blockers.length||!!plan.activeTasks.length" @click="remove"><Trash2 :size="17"/>{{busy?'正在删除…':'删除 '+plan.storyIds.length+' 本书'}}</button></div></template></div></Sheet></template>
<style scoped>.book-delete-names ul{max-height:180px;overflow:auto;overflow-wrap:anywhere;padding-left:20px}.book-delete-names li{padding:8px 0}.book-delete{display:grid;gap:24px}.book-delete h3{font:26px serif;margin:0 0 10px;overflow-wrap:anywhere}.book-delete header p{margin:0;font-size:13px}.book-delete-items{margin:0;padding:0;list-style:none;max-height:240px;overflow:auto}.book-delete-items li{display:flex;justify-content:space-between;gap:16px;padding:12px 0;border-bottom:1px solid var(--edge)}.book-delete-items span{min-width:0;overflow-wrap:anywhere}.book-delete-items small{white-space:nowrap;color:var(--muted)}.book-delete-blockers{padding:20px;background:var(--wash);border-radius:16px}.book-delete-blockers h4{margin:0 0 12px}.book-delete-blockers ul{padding-left:20px;max-height:180px;overflow:auto;overflow-wrap:anywhere}.book-delete details{border:1px solid var(--edge);border-radius:16px;padding:16px}.book-delete summary{display:flex;align-items:center;gap:8px;min-height:44px;cursor:pointer}.book-delete form{display:grid;gap:16px;margin-top:16px}.book-delete input:not([type=checkbox]){width:100%;min-height:44px}.book-delete-confirm{display:flex;align-items:center;gap:12px;min-height:44px;line-height:1.7}.book-delete-confirm input{width:20px;height:20px;flex:0 0 auto}.book-delete-actions{display:flex;justify-content:space-between;gap:12px}.book-delete button,.book-delete-result a{display:inline-flex;align-items:center;justify-content:center;gap:8px;min-height:44px}.book-delete-danger{background:#ad3e38;color:white;border-color:#ad3e38}.book-delete-danger:disabled{opacity:.45}.book-delete-result{display:grid;justify-items:start;gap:18px}</style>
